getApi.source:
import { PhoenixPerps } from '@phoenixperps/sdk';

const client = new PhoenixPerps(); // the key: PHOENIXPERPS_API_KEY
const platform = await client.platform.info();
console.log(platform);

package main

import (
	"context"
	"fmt"
	"log"

	phoenixperps "github.com/phoenixperps/sdk/go"
)

func main() {
	client, err := phoenixperps.NewClient() // the key: PHOENIXPERPS_API_KEY
	if err != nil {
		log.Fatal(err)
	}
	if err := run(context.Background(), client); err != nil {
		log.Fatal(err)
	}
}

func run(ctx context.Context, client *phoenixperps.Client) error {
	platform, err := client.Platform.Info(ctx)
	if err != nil {
		return err
	}
	fmt.Printf("%+v\n", platform)
	return nil
}

using PhoenixPerps;

using var client = new PhoenixPerpsClient(); // the key: PHOENIXPERPS_API_KEY
var platform = await client.Platform.InfoAsync();
Console.WriteLine(platform);

import com.phoenixperpsfunding.sdk.PhoenixPerpsClient;
import com.phoenixperpsfunding.sdk.gen.*;
import java.math.BigDecimal;
import java.util.List;

PhoenixPerpsClient client = PhoenixPerpsClient.fromEnv(); // the key: PHOENIXPERPS_API_KEY
Platform platform = client.platform().info();
System.out.println(platform);

use phoenixperps::*;

#[tokio::main]
async fn main() -> Result<()> {
    let client = Client::from_env()?; // the key: PHOENIXPERPS_API_KEY
    let platform = client.platform().info().await?;
    println!("{platform:?}");
    Ok(())
}

