for (const market of data) console.log(market.market);

package main

import (
	"context"
	"fmt"
	"log"

	phoenixperps "github.com/phoenixperps/sdk/go"
)

func main() {
	client, err := phoenixperps.NewClient() // the key: PHOENIXPERPS_API_KEY
	if err != nil {
		log.Fatal(err)
	}
	if err := run(context.Background(), client); err != nil {
		log.Fatal(err)
	}
}

func run(ctx context.Context, client *phoenixperps.Client) error {
	page, err := client.Markets.List(ctx)
	if err != nil {
		return err
	}
	for _, market := range page.Data {
		fmt.Println(market.Market)
	}
	return nil
}

using PhoenixPerps;

using var client = new PhoenixPerpsClient(); // the key: PHOENIXPERPS_API_KEY
var page = await client.Markets.ListAsync();
foreach (var market in page.Data)
    Console.WriteLine(market.Value);

import com.phoenixperpsfunding.sdk.PhoenixPerpsClient;
import com.phoenixperpsfunding.sdk.gen.*;
import java.math.BigDecimal;
import java.util.List;

PhoenixPerpsClient client = PhoenixPerpsClient.fromEnv(); // the key: PHOENIXPERPS_API_KEY
for (Market market : client.markets().list().data()) {
    System.out.println(market.market());
}

use phoenixperps::*;

